def solution(n, k, m):
    # Parse input from string
    import sys
    from io import StringIO
    sys.stdin = StringIO(n)
    if "\n" in n:
        lines = n.strip().split("\n")
    else:
        lines = [n.strip()]

    parts = []
    for line in lines:
        parts.extend(map(int, line.split()))

    if len(parts) >= 3:
        n, k, m = parts[0], parts[1], parts[2]
    else:
        # Fallback for single-line input with multiple spaces
        n, k, m = map(int, parts)

    MOD = 10**9 + 7

    # DP with memoization
    # state: (current_planet, visited_mask) -> count
    # visited_mask: integer bitmask representing visited planets

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(current, mask, count):
        if count == k:
            return 1

        total = 0
        # Try all next planets y from 1 to current + m
        for y in range(1, min(n, current + m) + 1):
            if not (mask & (1 << (y - 1))):  # y not visited
                total = (total + dp(y, mask | (1 << (y - 1)), count + 1)) % MOD
        return total

    # We can start from any planet 1 to n
    ans = 0
    for start in range(1, n + 1):
        ans = (ans + dp(start, 1 << (start - 1), 1)) % MOD

    return str(ans)

