def combination(n, k, mod):
    if k < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1
    if k > n // 2:
        k = n - k

    result = 1
    for i in range(k):
        result = result * (n - i) % mod
        result = result * pow(i + 1, mod - 2, mod) % mod
    return result

