    def cross_product(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    def check_edge_intersection(p1, q1, p2, q2):
        """Check if edges p1-q1 and p2-q2 intersect (properly, not sharing endpoints)"""
        d1 = cross_product(p2, q2, p1)
        d2 = cross_product(p2, q2, q1)
        d3 = cross_product(p1, q1, p2)
        d4 = cross_product(p1, q1, q2)

        if ((d1 > 0 and d2 < 0) or (d1 < 0 and d2 > 0)) and \
           ((d3 > 0 and d4 < 0) or (d3 < 0 and d4 > 0)):
            return True
        return False

    def is_valid_diagonal(i, k, polygon, n):
        """Check if diagonal from i to k is valid (inside polygon, doesn't intersect edges)"""
        for q in range(n):
            r = (q + 1) % n  # Next vertex forming edge
            # Skip edges sharing endpoints with diagonal
            if q == i or r == i or q == k or r == k:
                continue
            if check_edge_intersection(polygon[i], polygon[k], polygon[q], polygon[r]):
                return False
        return True

    dp = [[0] * n for _ in range(n)]

    # dp[i][j] = number of triangulations of sub-polygon with vertices i, i+1, ..., j
    # Base case: 2 consecutive vertices = 1 way (no triangulation needed)
    for i in range(n):
        dp[i][(i + 1) % n] = 1

    # Fill DP for increasing polygon sizes
    for length in range(2, n):  # Sub-polygon size (number of vertices - 1)
        for i in range(n):
            j = (i + length) % n

            if j < i:
                j = (j - i) % n + i
                # Need to handle circular properly
                # Actually, let's use linear indexing where j > i

            # For linear approach, only compute dp[i][j] where j > i
            # There are n-i-1 such pairs for length = j-i
            break

    # Better approach: dp[i][j] for j > i in linear index space
    # We map circular to linear by unwrapping

    linear_dp = [[0] * n for _ in range(n)]

    for i in range(n):
        linear_dp[i][i + 1] = 1 if i + 1 < n else linear_dp[i][i+1] = 1

    # Count triangulations - use the standard approach
    # dp[i][j] where i < j non-circularly
    dp = [[0] * n for _ in range(n)]
    for i in range(n - 1):
        dp[i][i + 1] = 1

    # Build for chain 0 to n-1
    for length in range(2, n):
        for i in range(n - length):
            j = i + length
            for k in range(i + 1, j):
                # Check if triangle (i, k, j) can be formed with valid diagonals
                # Diagonal (i, k) must be valid
                if is_valid_diagonal(i, k, vertices, n):
                    dp[i][j] = (dp[i][j] + dp[i][k] * dp[k][j]) % MOD

    # For circular polygon, the answer is dp[0][n-1]
    return str(dp[0][n - 1])


