def count_independent_sets(n, edges):
    # Build adjacency matrix
    adj = [[False]*n for _ in range(n)]
    for u, v in edges:
        u -= 1  # Convert to 0-indexed
        v -= 1
        adj[u][v] = adj[v][u] = True

    def is_independent(mask):
        # Check if the subset represented by mask is independent
        for i in range(n):
            if mask & (1 << i):
                # Vertex i is in the subset
                for j in range(i+1, n):
                    if mask & (1 << j) and adj[i][j]:
                        return False
        return True

    # Meet-in-the-middle
    mid = n // 2
    A = list(range(mid))
    B = list(range(mid, n))

    ann = set()
    for mask in range(1 << mid):
        if is_independent(mask):
            # For this independent set in A, compute the forbidden vertices in B
            forbidden = 0
            for i in range(mid):
                if mask & (1 << i):
                    for j in range(mid, n):
                        if adj[i][j]:
                            forbidden |= (1 << (j - mid))
            ann.add(forbidden)

    # Count subsets in B that are independent and don't conflict with A
    count = 0
    for mask in range(1 << (n - mid)):
        if is_independent_B(mask, ann):
