MOD = 1051131

def popcount(x):
    return bin(x).count('1')

def mat_mul(A, B, n):
    C = [[0] * n for _ in range(n)]
    for i in range(n):
        for k in range(n):
            if A[i][k] == 0:
                continue
            for j in range(n):
                if B[k][j] == 0:
                    continue
                C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD
    return C

def mat_pow(A, p, n):
    result = [[0] * n for _ in range(n)]
    for i in range(n):
        result[i][i] = 1
    base = A
    while p > 0:
        if p % 2 == 1:
            result = mat_mul(result, base, n)
        base = mat_mul(base, base, n)
        p //= 2
    return result

def solution(input_str):
    lines = input_str.strip().split('\n')
    parts = lines[0].split()
    m, t, s = int(parts[0]), int(parts[1]), int(parts[2])

    a = list(map(int, lines[1].split()))

    # Generate remaining a[i]
    n = 2 * m
    for i in range(s, n):
        a.append((101 * a[-1] + 10007) % 1051131)

    # Build transition matrix
    size = n
    M = [[0] * size for _ in range(size)]

    for i in range(size):
        for j in range(size):
            if i == j:
                M[i][j] = 1  # Stay
            else:
                M[i][j] = (1 << popcount(i + 1 & j + 1)) % MOD

    # Compute M^t
    Mt = mat_pow(M, t, size)

    # Initial distribution: a[i] after entering island i+1 from home
    # After t days, we multiply by M^t

    # Start state: dp[0][i] = a[i]
    # After t steps: dp[t] = Mt * dp[0]

    ans = [0] * size
    for i in range(size):
        Mi = Mt[i]
        for j in range(size):
            ans[i] = (ans[i] + Mi[j] * a[j]) % MOD
        # Wait, matrix multiplication: ans[i] = sum over j of Mt[i][j] * a[j]
        # So iterate j over columns, and multiply Mt[i][j] * a[j]

    # Let's fix the multiplication
    ans = [0] * size
    for i in range(size):
        total = 0
        for j in range(size):
            total = (total + Mt[i][j] * a[j]) % MOD
        ans[i] = total

