from collections import deque

def solution(n_str):
    """
    Finds the minimum number of subtractions needed to reduce n to zero.
    In each step, we can subtract any digit that appears in the current number.
    Uses a greedy approach: always subtract the largest digit.
    """
    try:
        n = int(n_str.strip())
    except (ValueError, AttributeError):
        return "0"

    if n == 0:
        return "0"

    # Greedy approach: always subtract the largest digit present in the number
    count = 0
    while n > 0:
        s = str(n)

        # Find the largest non-zero digit
        max_d = -1
        for c in s:
            if c.isdigit() and c != '0':
                max_d = max(max_d, int(c))

        if max_d == -1:
            # No non-zero digit found (shouldn't happen for n > 0)
            break

        n -= max_d
        count += 1

    return str(count)


