def solution(input_str):
    from collections import deque

    # Parse input
    lines = input_str.strip().split('\n')

    if len(lines) < 3:
        lines = lines[0].split()
        n = int(lines[0])
        x = []
        a = 0
        b = 0
    else:
        n = int(lines[0].split()[0])
        x = list(map(int, lines[1].split()))
        parts = lines[2].split()
        a, b = int(parts[0]), int(parts[1])

    # Edge case: already equal
    if a == b:
        return "0\n"

    # BFS: dist[diff] = minimum moves to reach (a - diff)
    max_diff = a - b
    dist = [-1] * (max_diff + 1)
    dist[0] = 0  # Start at value a (difference 0)

    queue = deque([0])

    # BFS exploration
    while queue:
        cur = queue.popleft()
        d = dist[cur]
        current_val = a - cur

        # Move 1: Subtract 1
        next_diff = cur + 1
        if next_diff <= max_diff and dist[next_diff] == -1:
            dist[next_diff] = d + 1
            queue.append(next_diff)
            if next_diff == max_diff:
                return f"{dist[next_diff]}\n"

        # Move 2: Subtract (current_val mod xi) for each xi
        for xi in x:
            remainder = current_val % xi
            if remainder > 0:
                next_diff = cur + remainder
                if next_diff <= max_diff and dist[next_diff] == -1:
                    dist[next_diff] = d + 1
                    queue.append(next_diff)
                    if next_diff == max_diff:
                        return f"{dist[next_diff]}\n"

    # Fallback if unreachable through direct paths
    return f"{dist[max_diff] if dist[max_diff] != -1 else 0}\n"

