        # Move 1: subtract 1
        next_diff = cur + 1
        if next_diff <= max_diff and dist[next_diff] == -1:
            dist[next_diff] = d + 1
            if next_diff == max_diff:
                return str(dist[next_diff]) + "\n"
            queue.append(next_diff)

        # Move 2: subtract (current_val mod xi)
        for xi in x:
            remainder = current_val % xi
            if remainder > 0:
                next_diff = cur + remainder
                if next_diff <= max_diff and dist[next_diff] == -1:
